import {
  concat,
  getAddress,
  keccak256,
  pad,
  type Address,
  type Hex,
} from 'viem'
import { type ChainMode } from '@/store/chainMode'

const ZERO_ADDRESS: Address = '0x0000000000000000000000000000000000000000'

/**
 * 每个链的工厂部署信息。
 * - factory   : 部署 proxy 的工厂合约地址
 * - initCode  : proxyInitCode() 的 hex（MinimalProxy creationCode +
 *               abi.encode(factory)）。由后端提供，先留空。
 */
export interface DepositFactoryConfig {
  chainId: number
  chainName: string
  factory: Address
  initCode: Hex
}

export const depositFactoriesByMode: Record<ChainMode, DepositFactoryConfig[]> = {
  testnet: [
    {
      chainId: 84532,
      chainName: 'Base Sepolia',
      factory: '0x29ce0867477df7867ea8fa863fe0a3596630b7a4',
      initCode:
        '',
    },
  ],
  mainnet: [],
}

/** CREATE2：keccak256(0xff ++ factory ++ salt ++ keccak256(initCode)) 取后 20 字节 */
export function computeDepositAddressFromSalt(
  factory: Address,
  salt: Hex,
  initCode: Hex,
): Address | null {
  if (factory === ZERO_ADDRESS || initCode === '0x') return null
  try {
    const raw = keccak256(
      concat(['0xff', factory, salt, keccak256(initCode)]),
    )
    return getAddress(`0x${raw.slice(26)}`)
  } catch {
    return null
  }
}

/** 对应工厂 getAddress(address _subject)：salt = keccak256(abi.encode(_subject)) */
export function computeDepositAddress(
  factory: Address,
  subject: Address,
  initCode: Hex,
): Address | null {
  const salt = keccak256(pad(subject, { size: 32 }))
  return computeDepositAddressFromSalt(factory, salt, initCode)
}